.changecanvas-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2530;
    background:
        linear-gradient(0deg, rgba(255,255,255,0.55), rgba(255,255,255,0.55)),
        repeating-linear-gradient(0deg, #eef1f6 0px, #eef1f6 31px, #dfe5ee 32px),
        repeating-linear-gradient(90deg, #eef1f6 0px, #eef1f6 31px, #dfe5ee 32px);
    border-radius: 16px;
}

.changecanvas-container * {
    box-sizing: border-box;
}

.changecanvas-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #102a54 0%, #1b3f7a 55%, #2e63b8 100%);
    color: #f2f6fd;
    border-radius: 14px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(16, 42, 84, 0.32);
}

.changecanvas-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.changecanvas-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffce8a;
    background: rgba(255, 206, 138, 0.14);
    border: 1px solid rgba(255, 206, 138, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.changecanvas-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfdcf2;
}

.changecanvas-context {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.changecanvas-context-item {
    background: #ffffff;
    border-radius: 12px;
    padding: 12px 14px;
    box-shadow: 0 4px 12px rgba(28, 37, 48, 0.07);
    border-left: 4px solid #2e63b8;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.changecanvas-context-k {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7385a0;
}

.changecanvas-context-v {
    font-size: 0.92rem;
    font-weight: 800;
    color: #102a54;
}

.changecanvas-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #43536b;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.changecanvas-period-counter #currentDay,
.changecanvas-period-counter #maxPeriods {
    font-weight: 800;
    color: #e07b1a;
}

.changecanvas-round-name {
    background: rgba(46, 99, 184, 0.14);
    color: #1b3f7a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.changecanvas-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b3640f;
    background: rgba(224, 123, 26, 0.13);
    border: 1px solid rgba(224, 123, 26, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.changecanvas-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.changecanvas-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.09);
    border-top: 4px solid #2e63b8;
    position: relative;
}

.changecanvas-card-adoption { border-top-color: #2e8b57; }
.changecanvas-card-resistance { border-top-color: #c0392b; }
.changecanvas-card-engagement { border-top-color: #7d5fc0; }
.changecanvas-card-budget { border-top-color: #e07b1a; }

.changecanvas-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7d96;
}

.changecanvas-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #102a54;
    font-variant-numeric: tabular-nums;
}

.changecanvas-card-adoption .changecanvas-value { color: #2e8b57; }
.changecanvas-card-resistance .changecanvas-value { color: #c0392b; }
.changecanvas-card-engagement .changecanvas-value { color: #7d5fc0; }
.changecanvas-card-budget .changecanvas-value { color: #c4690f; }

.changecanvas-sublabel {
    font-size: 0.76rem;
    color: #76879e;
    line-height: 1.35;
}

.changecanvas-card-adoption.changecanvas-adopt-danger { border-top-color: #c0392b; }
.changecanvas-card-adoption.changecanvas-adopt-danger .changecanvas-value { color: #c0392b; }
.changecanvas-card-adoption.changecanvas-adopt-good { border-top-color: #2e8b57; }
.changecanvas-card-adoption.changecanvas-adopt-good .changecanvas-value { color: #2e8b57; }

.changecanvas-embed-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde3ec;
    color: #43536b;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.changecanvas-embed-bar #embedDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c0392b;
    font-weight: 800;
}

.changecanvas-embed-bar.changecanvas-embed-good #embedDisplay { color: #2e8b57; }
.changecanvas-embed-bar.changecanvas-embed-mid #embedDisplay { color: #c4690f; }

.changecanvas-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf5;
    border-left: 5px solid #e07b1a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.07);
}

.changecanvas-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.changecanvas-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #102a54;
    margin-bottom: 6px;
}

.changecanvas-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4a5e;
}

.changecanvas-briefing-text strong { color: #1b3f7a; }
.changecanvas-briefing-text em { color: #c4690f; font-style: italic; }

.changecanvas-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.07);
}

.changecanvas-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #102a54;
    border-bottom: 2px solid #e7ecf3;
    padding-bottom: 8px;
}

.changecanvas-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3a4e;
    margin: 14px 0 6px;
}

.changecanvas-container select,
.changecanvas-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d0dd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2530;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.changecanvas-container select:focus,
.changecanvas-container input[type="number"]:focus {
    outline: none;
    border-color: #2e63b8;
    box-shadow: 0 0 0 3px rgba(46, 99, 184, 0.16);
}

.changecanvas-container select option {
    background-color: #ffffff;
    color: #1c2530;
}

.changecanvas-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e07b1a;
}

.changecanvas-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #43536b;
    margin-top: 4px;
}

.changecanvas-range-readout span:nth-child(2) {
    color: #e07b1a;
    font-weight: 800;
}

.changecanvas-hint {
    font-size: 0.8rem;
    color: #76879e;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.changecanvas-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.changecanvas-container .btn-primary {
    background: linear-gradient(135deg, #1b3f7a 0%, #2e63b8 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(27, 63, 122, 0.32);
}

.changecanvas-container .btn-primary:hover {
    filter: brightness(1.08);
}

.changecanvas-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d0dd;
    color: #5a6b82;
    background: transparent;
}

.changecanvas-coach {
    background: linear-gradient(160deg, #102a54 0%, #163464 100%);
    color: #dfe9fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(16, 42, 84, 0.26);
}

.changecanvas-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffce8a;
    margin-bottom: 8px;
}

.changecanvas-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.changecanvas-coach-body strong { color: #8fd3ad; }
.changecanvas-coach-body em { color: #ffce8a; font-style: italic; }

.changecanvas-history,
.changecanvas-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.07);
}

.changecanvas-history h3,
.changecanvas-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #102a54;
}

.changecanvas-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4a5e;
}

.changecanvas-container table#usfHistoryTable th {
    background: #eef3fa;
    color: #1b3f7a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e0ed;
}

.changecanvas-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f5;
    color: #3a4a5e;
}

.changecanvas-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.changecanvas-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .changecanvas-container {
        padding: 14px;
    }
    .changecanvas-header h1 {
        font-size: 1.7rem;
    }
    .changecanvas-context {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .changecanvas-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .changecanvas-value {
        font-size: 2rem;
    }
    .changecanvas-clock {
        margin-left: 0;
    }
    .changecanvas-period-counter {
        font-size: 0.88rem;
    }
    .changecanvas-embed-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .changecanvas-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.cc-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.cc-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7d8aa3; margin-bottom: 6px; }
.cc-cm-verdict { font-size: 22px; font-weight: 700; color: #ecf0f7; margin-bottom: 8px; }
.cc-cm-score { font-size: 16px; color: #ecf0f7; margin-bottom: 16px; }
.cc-cm-score strong { color: #7c5cff; }
.cc-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7d8aa3; margin-bottom: 8px; }
.cc-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.cc-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.cc-cm-target.cc-cm-met { background: rgba(124,92,255,0.18); color: #b9a6ff; border-color: rgba(124,92,255,0.42); }
.cc-cm-target.cc-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.cc-cm-tick { font-weight: 700; }
.cc-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.cc-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,140,180,0.12); border-radius: 8px; min-width: 92px; }
.cc-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7d8aa3; }
.cc-cm-metric strong { font-size: 16px; color: #ecf0f7; }
.cc-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.cc-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(124,92,255,0.10); border-left: 3px solid #7c5cff; border-radius: 4px; color: #dde2f0; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .cc-cm-metric { min-width: 70px; } .cc-cm-verdict { font-size: 19px; } }

