(function() {
    'use strict';

    class ChangeCanvasAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Change Canvas`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Maasland Verzekeringen N.V.).
            this.START_ADOPTION = 34;     // % daily active use
            this.START_RESISTANCE = 51;   // resistance index 0–100
            this.START_ENGAGEMENT = -14;  // engagement change vs baseline (points)
            this.START_BUDGET = 790;      // €K remaining of the €1.2M (≈€790K)
            this.START_EMBED = 7.0;       // modelled time-to-embed (months/team)
            this.TARGET_ADOPTION = 80;    // board target by month 9
            this.CANCEL_ADOPTION = 60;    // CFO cancel threshold (network-wide)
            this.PLATEAU = 40;            // historic adoption ceiling
            this.EMBED_TARGET = 5.0;      // ≈5 months/team if waves overlap

            // Concept truths (the modelled best answers).
            this.TRUE_ROOTCAUSE = `reinforcement`;
            this.TRUE_ORDER = `managersfirst`;
            this.TRUE_MECHANISM = `embed`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    adoption: this.START_ADOPTION,
                    resistance: this.START_RESISTANCE,
                    engagement: this.START_ENGAGEMENT,
                    budget: this.START_BUDGET,
                    embed: this.START_EMBED,
                    // Pattern flags wired to the five common errors.
                    broadcastBias: false,
                    frontlineFirst: false,
                    uniformHeavy: false,
                    momentumOverRescue: false,
                    launchAsSuccess: false,
                    managersEnabled: false,    // line managers enabled before frontline
                    overspent: false,          // ran the budget dry before the last waves
                    adoptionHistory: [this.START_ADOPTION],
                    resistanceHistory: [this.START_RESISTANCE],
                    engagementHistory: [this.START_ENGAGEMENT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    rootcause: `awareness`,
                    signal: `obstacle`,
                    stakeholder: `frontline`,
                    focus: 35,
                    intensity: `light`,
                    cadence: `oneoff`,
                    order: `frontlinefirst`,
                    managerspend: 20,
                    rescue: `pushforward`,
                    dosage: `alllight`,
                    waves: `bigbang`,
                    commit: `250`,
                    coalition: `overrule`,
                    regulatory: `pushboth`,
                    mechanism: `celebrate`,
                    board: `spin`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rc = document.getElementById(`rootcauseInput`);
                const si = document.getElementById(`signalInput`);
                const sk = document.getElementById(`stakeholderInput`);
                const fo = document.getElementById(`focusInput`);
                if (rc) decisions.rootcause = rc.value;
                if (si) decisions.signal = si.value;
                if (sk) decisions.stakeholder = sk.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const it = document.getElementById(`intensityInput`);
                const ca = document.getElementById(`cadenceInput`);
                const or = document.getElementById(`orderInput`);
                const ms = document.getElementById(`managerspendInput`);
                if (it) decisions.intensity = it.value;
                if (ca) decisions.cadence = ca.value;
                if (or) decisions.order = or.value;
                if (ms) decisions.managerspend = parseInt(ms.value, 10);
                if (!Number.isFinite(decisions.managerspend) || decisions.managerspend < 0 || decisions.managerspend > 100) {
                    warn(`warn_managerspend_range`); return false;
                }
            } else if (round === 3) {
                const re = document.getElementById(`rescueInput`);
                const do_ = document.getElementById(`dosageInput`);
                const wa = document.getElementById(`wavesInput`);
                const co = document.getElementById(`commitInput`);
                if (re) decisions.rescue = re.value;
                if (do_) decisions.dosage = do_.value;
                if (wa) decisions.waves = wa.value;
                if (co) decisions.commit = co.value;
                const spend = parseFloat(decisions.commit);
                if (!Number.isFinite(spend) || spend < 0) {
                    warn(`warn_commit_value`); return false;
                }
            } else if (round === 4) {
                const cl = document.getElementById(`coalitionInput`);
                const rg = document.getElementById(`regulatoryInput`);
                const me = document.getElementById(`mechanismInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (cl) decisions.coalition = cl.value;
                if (rg) decisions.regulatory = rg.value;
                if (me) decisions.mechanism = me.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let adoptionDelta = 0, resistanceDelta = 0, engagementDelta = 0;
            let embedDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: name the right gap, read resistance as signal, engage the multiplier.
                switch (d.rootcause) {
                    case `reinforcement`:
                        adoptionDelta += 4; resistanceDelta -= 6; engagementDelta += 2; embedDelta -= 0.4;
                        coachKey = `coach_r1_reinforcement`; break;
                    case `ability`:
                        adoptionDelta += 1; resistanceDelta -= 1; embedDelta -= 0.1;
                        coachKey = `coach_r1_ability`; break;
                    case `awareness`:
                        resistanceDelta += 5; embedDelta += 0.2; ds.broadcastBias = true;
                        coachKey = `coach_r1_awareness`; break;
                    case `resistance`:
                        resistanceDelta += 7; engagementDelta -= 3;
                        coachKey = `coach_r1_resistance`; break;
                }

                switch (d.signal) {
                    case `diagnostic`: resistanceDelta -= 5; engagementDelta += 2; break;
                    case `obstacle`: resistanceDelta += 5; engagementDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_obstacle`; break;
                    case `ignore`: resistanceDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r1_ignore`; break;
                }

                switch (d.stakeholder) {
                    case `managers`: adoptionDelta += 5; resistanceDelta -= 5; embedDelta -= 0.4; ds.managersEnabled = true; break;
                    case `sponsors`: resistanceDelta += 2; break;
                    case `frontline`: adoptionDelta += 1; resistanceDelta += 3; embedDelta += 0.2; break;
                }

                // Diagnostic focus on the reinforcement gap = procedural sharpness.
                if (d.focus >= 60 && d.rootcause === `reinforcement`) { adoptionDelta += 2; resistanceDelta -= 3; }
                else if (d.focus <= 20) { resistanceDelta += 2; }

                if (d.rootcause === `reinforcement` && d.signal === `diagnostic` && d.stakeholder === `managers`) {
                    coachKey = `coach_r1_sharp`;
                }
                summaryKey = (d.rootcause === `reinforcement` && d.signal === `diagnostic` && d.stakeholder === `managers`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Plan: intensity, cadence, engagement order, manager front-loading.
                // Intensity sets a baseline cost and embedding power.
                switch (d.intensity) {
                    case `light`:
                        spend += 120; adoptionDelta += 2; embedDelta += 0.2;
                        if (d.cadence === `oneoff`) coachKey = `coach_r2_light`;
                        break;
                    case `medium`:
                        spend += 240; adoptionDelta += 7; resistanceDelta -= 4; embedDelta -= 0.6;
                        break;
                    case `heavy`:
                        spend += 430; adoptionDelta += 11; resistanceDelta -= 6; embedDelta -= 1.0;
                        ds.uniformHeavy = true; coachKey = `coach_r2_heavy`;
                        break;
                }

                // Communication cadence (Common Error 1: broadcast bias).
                if (d.cadence === `sustained`) {
                    adoptionDelta += 5; resistanceDelta -= 8; engagementDelta += 3; embedDelta -= 0.4;
                } else { // oneoff broadcast
                    resistanceDelta += 6; engagementDelta -= 2; ds.broadcastBias = true;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_broadcast`;
                }

                // Engagement order (Common Error 2: frontline before managers).
                switch (d.order) {
                    case `managersfirst`:
                        adoptionDelta += 9; resistanceDelta -= 6; engagementDelta += 3; embedDelta -= 0.8;
                        ds.managersEnabled = true; coachKey = `coach_r2_managersfirst`; break;
                    case `parallel`:
                        adoptionDelta += 3; embedDelta -= 0.2; break;
                    case `frontlinefirst`:
                        adoptionDelta -= 4; resistanceDelta += 5; ds.frontlineFirst = true;
                        coachKey = `coach_r2_frontlinefirst`; break;
                }

                // Front-loading spend into manager enablement bends the curve.
                const mShare = d.managerspend / 100;
                spend += Math.round(40 * mShare); // a slice of phase spend dedicated to managers
                if (mShare >= 0.35) { adoptionDelta += 4; resistanceDelta -= 4; embedDelta -= 0.4; ds.managersEnabled = true; }
                else if (mShare <= 0.1) { adoptionDelta -= 2; resistanceDelta += 2; }

                summaryKey = (d.order === `managersfirst` && d.cadence === `sustained` && d.intensity !== `heavy`) ? `sum_r2_good` :
                             (d.intensity === `heavy` ? `sum_r2_heavy` :
                             (d.order === `frontlinefirst` ? `sum_r2_frontline` :
                             (d.cadence === `oneoff` ? `sum_r2_broadcast` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Decide: rescue vs momentum, dosage, wave sequencing, budget commit.
                spend += parseFloat(d.commit);

                // Rescue vs momentum (Common Error 4).
                switch (d.rescue) {
                    case `rescuefirst`:
                        adoptionDelta += 8; resistanceDelta -= 7; engagementDelta += 4; embedDelta -= 0.6;
                        coachKey = `coach_r3_rescue`; break;
                    case `pushforward`:
                        adoptionDelta -= 5; resistanceDelta += 8; engagementDelta -= 3; embedDelta += 0.5;
                        ds.momentumOverRescue = true; coachKey = `coach_r3_momentum`; break;
                    case `abandon`:
                        adoptionDelta -= 7; resistanceDelta += 6; engagementDelta -= 5;
                        ds.momentumOverRescue = true; coachKey = `coach_r3_abandon`; break;
                }

                // Dosage / rationing finite capacity (Common Error 3).
                switch (d.dosage) {
                    case `matched`:
                        adoptionDelta += 7; resistanceDelta -= 4; embedDelta -= 0.7; break;
                    case `allheavy`:
                        adoptionDelta += 4; resistanceDelta -= 2; embedDelta -= 0.3; ds.uniformHeavy = true;
                        coachKey = `coach_r3_allheavy`; break;
                    case `alllight`:
                        adoptionDelta -= 2; resistanceDelta += 3; embedDelta += 0.3;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_alllight`; break;
                }

                // Wave sequencing — overlapping ≈5 mo/team is the modelled fit to the window.
                switch (d.waves) {
                    case `overlapping`:
                        adoptionDelta += 4; embedDelta -= 0.9; resistanceDelta -= 2; break;
                    case `bigbang`:
                        adoptionDelta -= 3; resistanceDelta += 5; embedDelta += 0.4;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_bigbang`; break;
                    case `serial`:
                        embedDelta += 0.8; // safe per team but overruns the 9-month window
                        if (coachKey === `coach_default`) coachKey = `coach_r3_serial`; break;
                }

                summaryKey = (d.rescue === `rescuefirst` && d.dosage === `matched` && d.waves === `overlapping`) ? `sum_r3_good` :
                             (ds.momentumOverRescue ? `sum_r3_momentum` :
                             (d.dosage === `allheavy` ? `sum_r3_allheavy` :
                             (d.dosage === `alllight` ? `sum_r3_alllight` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Recover: coalition, regulatory shock, reinforcement mechanism, board framing.
                switch (d.coalition) {
                    case `convert`:
                        adoptionDelta += 6; resistanceDelta -= 10; engagementDelta += 5; embedDelta -= 0.5;
                        coachKey = `coach_r4_convert`; break;
                    case `overrule`:
                        resistanceDelta += 8; engagementDelta -= 8;
                        coachKey = `coach_r4_overrule`; break;
                    case `ignore`:
                        resistanceDelta += 5; engagementDelta -= 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r4_coalignore`; break;
                }

                switch (d.regulatory) {
                    case `protect`:
                        adoptionDelta += 4; resistanceDelta -= 4; embedDelta -= 0.3; break;
                    case `pushboth`:
                        adoptionDelta -= 4; resistanceDelta += 5; engagementDelta -= 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r4_pushboth`; break;
                    case `pause`:
                        adoptionDelta -= 6; embedDelta += 0.6; ds.launchAsSuccess = true;
                        if (coachKey === `coach_default`) coachKey = `coach_r4_pause`; break;
                }

                // The reinforcement mechanism (Common Error 5: launch-as-success).
                switch (d.mechanism) {
                    case `embed`:
                        adoptionDelta += 9; resistanceDelta -= 6; engagementDelta += 4; embedDelta -= 1.0;
                        if (d.coalition === `convert`) coachKey = `coach_r4_embed`; break;
                    case `audit`:
                        adoptionDelta += 1; resistanceDelta += 5; engagementDelta -= 3;
                        if (coachKey === `coach_default`) coachKey = `coach_r4_audit`; break;
                    case `celebrate`:
                        adoptionDelta -= 6; resistanceDelta += 4; ds.launchAsSuccess = true;
                        coachKey = `coach_r4_celebrate`; break;
                }

                switch (d.board) {
                    case `evidence`: adoptionDelta += 2; engagementDelta += 1; break;
                    case `spin`: resistanceDelta += 2; if (coachKey === `coach_default`) coachKey = `coach_r4_spin`; break;
                    case `defer`: spend += 0; if (coachKey === `coach_default`) coachKey = `coach_r4_defer`; break;
                }

                if (d.conviction >= 60) { resistanceDelta -= 3; engagementDelta += 1; }
                else if (d.conviction <= 25) { resistanceDelta += 3; }

                summaryKey = (d.coalition === `convert` && d.mechanism === `embed` && d.regulatory === `protect`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Budget: spend draws down the remaining change budget. ----
            if (spend > 0) {
                ds.budget = Math.max(0, Math.round(ds.budget - spend));
                if (ds.budget <= 60) {
                    // Ran the budget dry before the final waves — the uniform-heavy trap.
                    ds.overspent = true;
                    adoptionDelta -= 6; embedDelta += 0.5;
                    if (round === 3) coachKey = `coach_r3_overspent`;
                }
            }

            // ---- Apply deltas (clamped). ----
            ds.adoption = Math.max(0, Math.min(100, Math.round((ds.adoption + adoptionDelta) * 10) / 10));
            ds.resistance = Math.max(0, Math.min(100, Math.round(ds.resistance + resistanceDelta)));
            ds.engagement = Math.max(-40, Math.min(40, Math.round(ds.engagement + engagementDelta)));
            ds.embed = Math.max(3.0, Math.min(12.0, Math.round((ds.embed + embedDelta) * 10) / 10));

            // ---- Launch-as-success decay: behaviour trained but not reinforced slides
            // back toward the historic 40% plateau. ----
            if (ds.launchAsSuccess && !ds.managersEnabled) {
                ds.adoption = Math.max(this.PLATEAU, Math.round(ds.adoption - 4));
                if (ds.adoption > this.PLATEAU + 6) ds.adoption = this.PLATEAU + 6;
            }
            // ---- Frontline-before-managers collapses adoption back toward the plateau. ----
            if (ds.frontlineFirst && !ds.managersEnabled && ds.adoption > this.PLATEAU) {
                ds.adoption = Math.max(this.PLATEAU, Math.round(ds.adoption - 5));
            }

            ds.adoptionHistory.push(ds.adoption);
            ds.resistanceHistory.push(ds.resistance);
            ds.engagementHistory.push(ds.engagement);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                adoption: ds.adoption,
                adoptionDelta: Math.round(adoptionDelta * 10) / 10,
                resistance: ds.resistance,
                resistanceDelta: Math.round(resistanceDelta),
                engagement: ds.engagement,
                budget: ds.budget,
                spend: Math.round(spend),
                embed: ds.embed,
                overspent: ds.overspent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _embedClass(v) {
            if (v <= 5.0) return `good`;
            if (v <= 6.0) return `mid`;
            return `high`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`adoptionDisplay`, `domainState.adoption`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.changecanvas-card-adoption`);
                if (card) {
                    card.classList.toggle(`changecanvas-adopt-danger`, n < self.CANCEL_ADOPTION);
                    card.classList.toggle(`changecanvas-adopt-good`, n >= self.TARGET_ADOPTION);
                }
                return `${n}%`;
            });

            uiManager.bind(`resistanceDisplay`, `domainState.resistance`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => {
                const n = Math.round(Number(v));
                return n > 0 ? `+${n}` : `${n}`;
            });

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => `€${Math.round(Number(v))}K`);

            uiManager.bind(`embedDisplay`, `domainState.embed`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.changecanvas-embed-bar`);
                if (bar) {
                    const cls = self._embedClass(n);
                    bar.classList.toggle(`changecanvas-embed-good`, cls === `good`);
                    bar.classList.toggle(`changecanvas-embed-mid`, cls === `mid`);
                }
                return `${self._fmtMonths(n)} ${window.mySimulation.t(`unit_mo`)}`;
            });

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Manager-spend slider readout.
            const ms = document.getElementById(`managerspendInput`);
            const msReadout = document.getElementById(`managerspendReadout`);
            if (ms && msReadout) {
                msReadout.textContent = ms.value;
                ms.addEventListener(`input`, function() { msReadout.textContent = ms.value; });
            }
        }

        _fmtMonths(v) {
            // Locale-aware one-decimal: en "7.0", es "7,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = v.toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

