        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.adoptionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Engagement is a -40..+40 delta — offset by +50 so it shares the 0–100 axis.
            const engagementShifted = ds.engagementHistory.map((v) => Math.round(v + 50));
            return {
                changeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.adoptionHistory.map((v) => Math.round(v)) },
                        { data: ds.resistanceHistory },
                        { data: engagementShifted }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.42/0.24/0.16/0.18 sum to 1).
            const adoption = Math.round(ds.adoption);
            const resistance = Math.round(ds.resistance);
            const engagement = Math.round(ds.engagement);
            const embed = Math.round(ds.embed * 10) / 10;
            const resistScore = 100 - resistance;
            const engageScore = Math.max(0, Math.min(100, (engagement + 20) * 2.5));
            const embedScore = Math.max(0, Math.min(100, (8 - embed) / 4 * 100));
            return Math.round(adoption * 0.42 + resistScore * 0.24 + engageScore * 0.16 + embedScore * 0.18);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="cc-cm-target ' + (ok ? 'cc-cm-met' : 'cc-cm-missed') + '">'
                    + '<span class="cc-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.onTarget, t('tgt_adoption'))
                + chip(!!summary.aboveCancel, t('tgt_cancel'))
                + chip(!!summary.resistanceFell, t('tgt_resistance'))
                + chip(!!summary.embedded, t('tgt_embed'));
            const metric = function (label, val) {
                return '<div class="cc-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const eng = summary.engagement;
            const engStr = (eng != null) ? ((eng > 0 ? '+' : '') + eng) : '-';
            const metrics = ''
                + metric(t('kpi_adoption'), (summary.adoption != null ? summary.adoption : '-') + '%')
                + metric(t('kpi_resistance'), (summary.resistance != null ? summary.resistance : '-') + '/100')
                + metric(t('kpi_engagement'), engStr)
                + metric(t('kpi_budget'), '€' + (summary.budget != null ? summary.budget : '-') + 'K')
                + metric(t('kpi_embed'), (summary.embed != null ? summary.embed : '-') + ' mo');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="cc-cm">'
                +   '<div class="cc-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="cc-cm-verdict">' + verdict + '</div>'
                +   '<div class="cc-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="cc-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="cc-cm-targets">' + targets + '</div>'
                +   '<div class="cc-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="cc-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const adoption = Math.round(ds.adoption);
            const resistance = Math.round(ds.resistance);
            const engagement = Math.round(ds.engagement);
            const budget = Math.round(ds.budget);
            const embed = Math.round(ds.embed * 10) / 10;

            // Composite: adoption is the headline, resistance and engagement and embedding round it out.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            const onTarget = adoption >= this.TARGET_ADOPTION;
            const aboveCancel = adoption >= this.CANCEL_ADOPTION;
            const resistanceFell = resistance <= 35;
            const embedded = embed <= this.EMBED_TARGET;

            let pattern = `mixed`;
            if (ds.launchAsSuccess && adoption <= this.PLATEAU + 8) pattern = `decay`;
            else if (ds.frontlineFirst && !ds.managersEnabled) pattern = `nomultiplier`;
            else if (ds.broadcastBias && resistance >= 50) pattern = `broadcast`;
            else if (ds.uniformHeavy && ds.overspent) pattern = `overspent`;
            else if (ds.momentumOverRescue && adoption < this.CANCEL_ADOPTION) pattern = `momentum`;
            else if (onTarget && resistanceFell && embedded) pattern = `embedded`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (onTarget && resistanceFell && embedded && composite >= 75) perfKey = `grade_embedded`;
            else if (aboveCancel && resistance < 45 && composite >= 60) perfKey = `grade_renewal`;
            else if (pattern === `decay`) perfKey = `grade_decay`;
            else if (pattern === `nomultiplier`) perfKey = `grade_nomultiplier`;
            else if (pattern === `broadcast`) perfKey = `grade_broadcast`;
            else if (pattern === `overspent`) perfKey = `grade_overspent`;
            else if (pattern === `momentum`) perfKey = `grade_momentum`;
            else if (composite >= 50) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (onTarget && resistanceFell && embedded) insights.push(window.mySimulation.t(`insight_embedded`));
            else if (pattern === `decay`) insights.push(window.mySimulation.t(`insight_decay`));
            else if (pattern === `nomultiplier`) insights.push(window.mySimulation.t(`insight_nomultiplier`));
            else if (pattern === `broadcast`) insights.push(window.mySimulation.t(`insight_broadcast`));
            else if (pattern === `overspent`) insights.push(window.mySimulation.t(`insight_overspent`));
            else if (pattern === `momentum`) insights.push(window.mySimulation.t(`insight_momentum`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!aboveCancel) insights.push(window.mySimulation.t(`insight_cancelled`));
            if (resistance >= 55) insights.push(window.mySimulation.t(`insight_resistance_high`));
            if (!embedded && onTarget) insights.push(window.mySimulation.t(`insight_slow_embed`));
            if (ds.managersEnabled && onTarget) insights.push(window.mySimulation.t(`insight_multiplier_used`));
            if (budget <= 60) insights.push(window.mySimulation.t(`insight_nobudget`));

            return {
                gradeKey: perfKey,
                score: composite,
                adoption: adoption,
                resistance: resistance,
                engagement: engagement,
                budget: budget,
                embed: embed,
                onTarget: onTarget,
                aboveCancel: aboveCancel,
                resistanceFell: resistanceFell,
                embedded: embedded,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.adoption < this.CANCEL_ADOPTION && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cancel`);
            if (ds.frontlineFirst && !ds.managersEnabled) return window.mySimulation.t(`hint_managers`);
            if (ds.broadcastBias && ds.resistance >= 50) return window.mySimulation.t(`hint_broadcast`);
            if (ds.uniformHeavy && ds.budget <= 120) return window.mySimulation.t(`hint_budget`);
            if (ds.momentumOverRescue) return window.mySimulation.t(`hint_rescue`);
            if (ds.launchAsSuccess) return window.mySimulation.t(`hint_reinforce`);
            if (ds.adoption >= this.TARGET_ADOPTION && ds.resistance <= 35) return window.mySimulation.t(`hint_strong`);
            return null;
        }

