            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.adoption`, label: `Adoption`, i18nKey: `col_adoption`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.resistance`, label: `Resistance`, i18nKey: `col_resistance`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.budget`, label: `Budget`, i18nKey: `col_budget`, formatter: (v) => `€${Math.round(v)}K` },
                { key: `results.embed`, label: `Embed`, i18nKey: `col_embed`, formatter: (v) => `${(Math.round(Number(v) * 10) / 10)}` }
            ];
        }

