                    resistance_sub:         `0–100, lower is safer · up from 28 pre-launch · a signal, not an obstacle`,
                    engagement_label:       `Engagement Change`,
                    engagement_sub:         `Points vs. baseline among live users · attrition rising in reverted teams`,
                    budget_label:           `Budget Remaining`,
